using FixFinder.Core.LocalFixes;
using FixFinder.Core.Logic;

namespace FixFinder.Tests;

/// <summary>
/// Two comparisons of one number joined by an and or an or that decide less than they seem to, in TypeScript, Ruby, PHP,
/// Lua, Perl, Dart, PowerShell, Scala, Fortran, Rust, Elixir, Erlang, F# and OCaml: mark &gt; 100 and mark &lt; 0, never true;
/// answer != 1 or answer != 2, always true; score &gt;= 50 and score &gt; 40, whose second half adds nothing. Left alone in each: a
/// range with each side facing in, the outside of a range, and an or whose second half an and takes first.
/// </summary>
public class OneNumberComparisonTests
{
    private static IReadOnlyList<LogicFinding> Scanned(string fileName, string code) =>
        LogicPatterns.Scan(new SourceFile { Path = Path.Combine(Path.GetTempPath(), fileName), Lines = code.Replace("\r\n", "\n").Split('\n') })
            .Where(finding => finding.PatternId.EndsWith("-comparisons-of-one-number", StringComparison.Ordinal))
            .ToList();

    /// <summary>The file, the program, and what the check said of it here: each finding's line, check and words, one a line.</summary>
    public static TheoryData<string, string, string> Found => new()
    {
        { "Grade.scala", "object Grade {\n  def grade(mark: Int, answer: Int, score: Int): String = {\n    if (mark > 100 && mark < 0) {\n      return \"impossible\"\n    }\n    if (answer != 1 || answer != 2) {\n      return \"always\"\n    }\n    if (score >= 50 && score > 40) {\n      return \"pass\"\n    }\n    \"fail\"\n  }\n\n  def main(args: Array[String]): Unit = {\n    println(grade(50, 1, 60))\n  }\n}\n", "3|logic-scala-comparisons-of-one-number|`mark > 100` and `mark < 0` cannot both be true - no number makes both hold - so `mark > 100 && mark < 0` is never true, and what it decides never happens\n6|logic-scala-comparisons-of-one-number|`answer != 1 || answer != 2` is always true - every number makes `answer != 1` or `answer != 2` hold - so it decides nothing\n9|logic-scala-comparisons-of-one-number|`score > 40` adds nothing to `score >= 50`: every number that makes `score >= 50` hold makes `score > 40` hold too, so `score >= 50 && score > 40` is the same as `score >= 50` - if a range was meant, one side may face the wrong way" },
        { "grade.dart", "String grade(int mark, int answer, int score) {\n  if (mark > 100 && mark < 0) {\n    return 'impossible';\n  }\n  if (answer != 1 || answer != 2) {\n    return 'always';\n  }\n  if (score >= 50 && score > 40) {\n    return 'pass';\n  }\n  return 'fail';\n}\n\nvoid main() {\n  print(grade(50, 1, 60));\n}\n", "2|logic-dart-comparisons-of-one-number|`mark > 100` and `mark < 0` cannot both be true - no number makes both hold - so `mark > 100 && mark < 0` is never true, and what it decides never happens\n5|logic-dart-comparisons-of-one-number|`answer != 1 || answer != 2` is always true - every number makes `answer != 1` or `answer != 2` hold - so it decides nothing\n8|logic-dart-comparisons-of-one-number|`score > 40` adds nothing to `score >= 50`: every number that makes `score >= 50` hold makes `score > 40` hold too, so `score >= 50 && score > 40` is the same as `score >= 50` - if a range was meant, one side may face the wrong way" },
        { "grade.erl", "-module(grade).\n-export([main/0]).\n\ngrade(Mark, Answer, Score) ->\n    if\n        Mark > 100 andalso Mark < 0 -> impossible;\n        Answer =/= 1 orelse Answer =/= 2 -> always;\n        Score >= 50 andalso Score > 40 -> pass;\n        true -> fail\n    end.\n\nmain() ->\n    io:format(\"~p~n\", [grade(50, 1, 60)]).\n", "6|logic-erlang-comparisons-of-one-number|`Mark > 100` and `Mark < 0` cannot both be true - no number makes both hold - so `Mark > 100 andalso Mark < 0` is never true, and what it decides never happens\n7|logic-erlang-comparisons-of-one-number|`Answer =/= 1 orelse Answer =/= 2` is always true - every number makes `Answer =/= 1` or `Answer =/= 2` hold - so it decides nothing\n8|logic-erlang-comparisons-of-one-number|`Score > 40` adds nothing to `Score >= 50`: every number that makes `Score >= 50` hold makes `Score > 40` hold too, so `Score >= 50 andalso Score > 40` is the same as `Score >= 50` - if a range was meant, one side may face the wrong way" },
        { "grade.exs", "defmodule Grade do\n  def grade(mark, answer, score) do\n    cond do\n      mark > 100 and mark < 0 -> \"impossible\"\n      answer != 1 or answer != 2 -> \"always\"\n      score >= 50 and score > 40 -> \"pass\"\n      true -> \"fail\"\n    end\n  end\nend\n\nIO.puts(Grade.grade(50, 1, 60))\n", "4|logic-elixir-comparisons-of-one-number|`mark > 100` and `mark < 0` cannot both be true - no number makes both hold - so `mark > 100 and mark < 0` is never true, and what it decides never happens\n5|logic-elixir-comparisons-of-one-number|`answer != 1 or answer != 2` is always true - every number makes `answer != 1` or `answer != 2` hold - so it decides nothing\n6|logic-elixir-comparisons-of-one-number|`score > 40` adds nothing to `score >= 50`: every number that makes `score >= 50` hold makes `score > 40` hold too, so `score >= 50 and score > 40` is the same as `score >= 50` - if a range was meant, one side may face the wrong way" },
        { "grade.f90", "program main\n  implicit none\n  print *, grade(50, 1, 60)\ncontains\n  integer function grade(mark, answer, score)\n    integer, intent(in) :: mark, answer, score\n    grade = 0\n    if (mark > 100 .and. mark < 0) grade = 1\n    if (answer /= 1 .or. answer /= 2) grade = 2\n    if (score >= 50 .and. score > 40) grade = 3\n  end function grade\nend program main\n", "8|logic-fortran-comparisons-of-one-number|`mark > 100` and `mark < 0` cannot both be true - no number makes both hold - so `mark > 100 .and. mark < 0` is never true, and what it decides never happens\n9|logic-fortran-comparisons-of-one-number|`answer /= 1 .or. answer /= 2` is always true - every number makes `answer /= 1` or `answer /= 2` hold - so it decides nothing\n10|logic-fortran-comparisons-of-one-number|`score > 40` adds nothing to `score >= 50`: every number that makes `score >= 50` hold makes `score > 40` hold too, so `score >= 50 .and. score > 40` is the same as `score >= 50` - if a range was meant, one side may face the wrong way" },
        { "grade.fsx", "let grade mark answer score =\n    if mark > 100 && mark < 0 then \"impossible\"\n    elif answer <> 1 || answer <> 2 then \"always\"\n    elif score >= 50 && score > 40 then \"pass\"\n    else \"fail\"\n\nprintfn \"%s\" (grade 50 1 60)\n", "2|logic-fsharp-comparisons-of-one-number|`mark > 100` and `mark < 0` cannot both be true - no number makes both hold - so `mark > 100 && mark < 0` is never true, and what it decides never happens\n3|logic-fsharp-comparisons-of-one-number|`answer <> 1 || answer <> 2` is always true - every number makes `answer <> 1` or `answer <> 2` hold - so it decides nothing\n4|logic-fsharp-comparisons-of-one-number|`score > 40` adds nothing to `score >= 50`: every number that makes `score >= 50` hold makes `score > 40` hold too, so `score >= 50 && score > 40` is the same as `score >= 50` - if a range was meant, one side may face the wrong way" },
        { "grade.lua", "local function grade(mark, answer, score)\n  if mark > 100 and mark < 0 then\n    return \"impossible\"\n  end\n  if answer ~= 1 or answer ~= 2 then\n    return \"always\"\n  end\n  if score >= 50 and score > 40 then\n    return \"pass\"\n  end\n  return \"fail\"\nend\n\nprint(grade(50, 1, 60))\n", "2|logic-lua-comparisons-of-one-number|`mark > 100` and `mark < 0` cannot both be true - no number makes both hold - so `mark > 100 and mark < 0` is never true, and what it decides never happens\n5|logic-lua-comparisons-of-one-number|`answer ~= 1 or answer ~= 2` is always true - every number makes `answer ~= 1` or `answer ~= 2` hold - so it decides nothing\n8|logic-lua-comparisons-of-one-number|`score > 40` adds nothing to `score >= 50`: every number that makes `score >= 50` hold makes `score > 40` hold too, so `score >= 50 and score > 40` is the same as `score >= 50` - if a range was meant, one side may face the wrong way" },
        { "grade.ml", "let grade mark answer score =\n  if mark > 100 && mark < 0 then \"impossible\"\n  else if answer <> 1 || answer <> 2 then \"always\"\n  else if score >= 50 && score > 40 then \"pass\"\n  else \"fail\"\n\nlet () = print_endline (grade 50 1 60)\n", "2|logic-ocaml-comparisons-of-one-number|`mark > 100` and `mark < 0` cannot both be true - no number makes both hold - so `mark > 100 && mark < 0` is never true, and what it decides never happens\n3|logic-ocaml-comparisons-of-one-number|`answer <> 1 || answer <> 2` is always true - every number makes `answer <> 1` or `answer <> 2` hold - so it decides nothing\n4|logic-ocaml-comparisons-of-one-number|`score > 40` adds nothing to `score >= 50`: every number that makes `score >= 50` hold makes `score > 40` hold too, so `score >= 50 && score > 40` is the same as `score >= 50` - if a range was meant, one side may face the wrong way" },
        { "grade.php", "<?php\nfunction grade(int $mark, int $answer, int $score): string\n{\n    if ($mark > 100 && $mark < 0) {\n        return \"impossible\";\n    }\n    if ($answer != 1 || $answer != 2) {\n        return \"always\";\n    }\n    if ($score >= 50 && $score > 40) {\n        return \"pass\";\n    }\n    return \"fail\";\n}\n\necho grade(50, 1, 60), PHP_EOL;\n", "4|logic-php-comparisons-of-one-number|`$mark > 100` and `$mark < 0` cannot both be true - no number makes both hold - so `$mark > 100 && $mark < 0` is never true, and what it decides never happens\n7|logic-php-comparisons-of-one-number|`$answer != 1 || $answer != 2` is always true - every number makes `$answer != 1` or `$answer != 2` hold - so it decides nothing\n10|logic-php-comparisons-of-one-number|`$score > 40` adds nothing to `$score >= 50`: every number that makes `$score >= 50` hold makes `$score > 40` hold too, so `$score >= 50 && $score > 40` is the same as `$score >= 50` - if a range was meant, one side may face the wrong way" },
        { "grade.pl", "use strict;\nuse warnings;\n\nsub grade {\n    my ($mark, $answer, $score) = @_;\n    return \"impossible\" if $mark > 100 && $mark < 0;\n    return \"always\" if $answer != 1 || $answer != 2;\n    return \"pass\" if $score >= 50 && $score > 40;\n    return \"fail\";\n}\n\nprint grade(50, 1, 60), \"\\n\";\n", "6|logic-perl-comparisons-of-one-number|`$mark > 100` and `$mark < 0` cannot both be true - no number makes both hold - so `$mark > 100 && $mark < 0` is never true, and what it decides never happens\n7|logic-perl-comparisons-of-one-number|`$answer != 1 || $answer != 2` is always true - every number makes `$answer != 1` or `$answer != 2` hold - so it decides nothing\n8|logic-perl-comparisons-of-one-number|`$score > 40` adds nothing to `$score >= 50`: every number that makes `$score >= 50` hold makes `$score > 40` hold too, so `$score >= 50 && $score > 40` is the same as `$score >= 50` - if a range was meant, one side may face the wrong way" },
        { "grade.ps1", "function Get-Grade($mark, $answer, $score) {\n    if ($mark -gt 100 -and $mark -lt 0) {\n        return \"impossible\"\n    }\n    if ($answer -ne 1 -or $answer -ne 2) {\n        return \"always\"\n    }\n    if ($score -ge 50 -and $score -gt 40) {\n        return \"pass\"\n    }\n    return \"fail\"\n}\n\nGet-Grade 50 1 60\n", "2|logic-powershell-comparisons-of-one-number|`$mark -gt 100` and `$mark -lt 0` cannot both be true - no number makes both hold - so `$mark -gt 100 -and $mark -lt 0` is never true, and what it decides never happens\n5|logic-powershell-comparisons-of-one-number|`$answer -ne 1 -or $answer -ne 2` is always true - every number makes `$answer -ne 1` or `$answer -ne 2` hold - so it decides nothing\n8|logic-powershell-comparisons-of-one-number|`$score -gt 40` adds nothing to `$score -ge 50`: every number that makes `$score -ge 50` hold makes `$score -gt 40` hold too, so `$score -ge 50 -and $score -gt 40` is the same as `$score -ge 50` - if a range was meant, one side may face the wrong way" },
        { "grade.rb", "def grade(mark, answer, score)\n  return \"impossible\" if mark > 100 && mark < 0\n  return \"always\" if answer != 1 || answer != 2\n  return \"pass\" if score >= 50 && score > 40\n  \"fail\"\nend\n\nputs grade(50, 1, 60)\n", "2|logic-ruby-comparisons-of-one-number|`mark > 100` and `mark < 0` cannot both be true - no number makes both hold - so `mark > 100 && mark < 0` is never true, and what it decides never happens\n3|logic-ruby-comparisons-of-one-number|`answer != 1 || answer != 2` is always true - every number makes `answer != 1` or `answer != 2` hold - so it decides nothing\n4|logic-ruby-comparisons-of-one-number|`score > 40` adds nothing to `score >= 50`: every number that makes `score >= 50` hold makes `score > 40` hold too, so `score >= 50 && score > 40` is the same as `score >= 50` - if a range was meant, one side may face the wrong way" },
        { "grade.rs", "fn grade(mark: i32, answer: i32, score: i32) -> &'static str {\n    if mark > 100 && mark < 0 {\n        return \"impossible\";\n    }\n    if answer != 1 || answer != 2 {\n        return \"always\";\n    }\n    if score >= 50 && score > 40 {\n        return \"pass\";\n    }\n    \"fail\"\n}\n\nfn main() {\n    println!(\"{}\", grade(50, 1, 60));\n}\n", "2|logic-rust-comparisons-of-one-number|`mark > 100` and `mark < 0` cannot both be true - no number makes both hold - so `mark > 100 && mark < 0` is never true, and what it decides never happens\n5|logic-rust-comparisons-of-one-number|`answer != 1 || answer != 2` is always true - every number makes `answer != 1` or `answer != 2` hold - so it decides nothing\n8|logic-rust-comparisons-of-one-number|`score > 40` adds nothing to `score >= 50`: every number that makes `score >= 50` hold makes `score > 40` hold too, so `score >= 50 && score > 40` is the same as `score >= 50` - if a range was meant, one side may face the wrong way" },
        { "grade.ts", "function grade(mark: number, answer: number, score: number): string {\n  if (mark > 100 && mark < 0) {\n    return \"impossible\";\n  }\n  if (answer !== 1 || answer !== 2) {\n    return \"always\";\n  }\n  if (score >= 50 && score > 40) {\n    return \"pass\";\n  }\n  return \"fail\";\n}\n\nconsole.log(grade(50, 1, 60));\n", "2|logic-typescript-comparisons-of-one-number|`mark > 100` and `mark < 0` cannot both be true - no number makes both hold - so `mark > 100 && mark < 0` is never true, and what it decides never happens\n5|logic-typescript-comparisons-of-one-number|`answer !== 1 || answer !== 2` is always true - every number makes `answer !== 1` or `answer !== 2` hold - so it decides nothing\n8|logic-typescript-comparisons-of-one-number|`score > 40` adds nothing to `score >= 50`: every number that makes `score >= 50` hold makes `score > 40` hold too, so `score >= 50 && score > 40` is the same as `score >= 50` - if a range was meant, one side may face the wrong way" },
    };

    /// <summary>The file, and a program of near misses the check must leave alone.</summary>
    public static TheoryData<string, string> NearMisses => new()
    {
        { "Grade.scala", "object Grade {\n  def grade(mark: Int, answer: Int, score: Int): String = {\n    if (mark >= 0 && mark <= 100) {\n      return \"impossible\"\n    }\n    if (mark < 0 || mark > 100) {\n      return \"always\"\n    }\n    if (score > 90 || score > 80 && answer > 10) {\n      return \"pass\"\n    }\n    \"fail\"\n  }\n\n  def main(args: Array[String]): Unit = {\n    println(grade(50, 1, 60))\n  }\n}\n" },
        { "grade.dart", "String grade(int mark, int answer, int score) {\n  if (mark >= 0 && mark <= 100) {\n    return 'impossible';\n  }\n  if (mark < 0 || mark > 100) {\n    return 'always';\n  }\n  if (score > 90 || score > 80 && answer > 10) {\n    return 'pass';\n  }\n  return 'fail';\n}\n\nvoid main() {\n  print(grade(50, 1, 60));\n}\n" },
        { "grade.erl", "-module(grade).\n-export([main/0]).\n\ngrade(Mark, Answer, Score) ->\n    if\n        Mark >= 0 andalso Mark =< 100 -> impossible;\n        Mark < 0 orelse Mark > 100 -> always;\n        Score > 90 orelse Score > 80 andalso Answer > 10 -> pass;\n        true -> fail\n    end.\n\nmain() ->\n    io:format(\"~p~n\", [grade(50, 1, 60)]).\n" },
        { "grade.exs", "defmodule Grade do\n  def grade(mark, answer, score) do\n    cond do\n      mark >= 0 and mark <= 100 -> \"impossible\"\n      mark < 0 or mark > 100 -> \"always\"\n      score > 90 or score > 80 and answer > 10 -> \"pass\"\n      true -> \"fail\"\n    end\n  end\nend\n\nIO.puts(Grade.grade(50, 1, 60))\n" },
        { "grade.f90", "program main\n  implicit none\n  print *, grade(50, 1, 60)\ncontains\n  integer function grade(mark, answer, score)\n    integer, intent(in) :: mark, answer, score\n    grade = 0\n    if (mark >= 0 .and. mark <= 100) grade = 1\n    if (mark < 0 .or. mark > 100) grade = 2\n    if (score > 90 .or. score > 80 .and. answer > 10) grade = 3\n  end function grade\nend program main\n" },
        { "grade.fsx", "let grade mark answer score =\n    if mark >= 0 && mark <= 100 then \"impossible\"\n    elif mark < 0 || mark > 100 then \"always\"\n    elif score > 90 || score > 80 && answer > 10 then \"pass\"\n    else \"fail\"\n\nprintfn \"%s\" (grade 50 1 60)\n" },
        { "grade.lua", "local function grade(mark, answer, score)\n  if mark >= 0 and mark <= 100 then\n    return \"impossible\"\n  end\n  if mark < 0 or mark > 100 then\n    return \"always\"\n  end\n  if score > 90 or score > 80 and answer > 10 then\n    return \"pass\"\n  end\n  return \"fail\"\nend\n\nprint(grade(50, 1, 60))\n" },
        { "grade.ml", "let grade mark answer score =\n  if mark >= 0 && mark <= 100 then \"impossible\"\n  else if mark < 0 || mark > 100 then \"always\"\n  else if score > 90 || score > 80 && answer > 10 then \"pass\"\n  else \"fail\"\n\nlet () = print_endline (grade 50 1 60)\n" },
        { "grade.php", "<?php\nfunction grade(int $mark, int $answer, int $score): string\n{\n    if ($mark >= 0 && $mark <= 100) {\n        return \"impossible\";\n    }\n    if ($mark < 0 || $mark > 100) {\n        return \"always\";\n    }\n    if ($score > 90 || $score > 80 && $answer > 10) {\n        return \"pass\";\n    }\n    return \"fail\";\n}\n\necho grade(50, 1, 60), PHP_EOL;\n" },
        { "grade.pl", "use strict;\nuse warnings;\n\nsub grade {\n    my ($mark, $answer, $score) = @_;\n    return \"impossible\" if $mark >= 0 && $mark <= 100;\n    return \"always\" if $mark < 0 || $mark > 100;\n    return \"pass\" if $score > 90 || $score > 80 && $answer > 10;\n    return \"fail\";\n}\n\nprint grade(50, 1, 60), \"\\n\";\n" },
        { "grade.ps1", "function Get-Grade($mark, $answer, $score) {\n    if ($mark -ge 0 -and $mark -le 100) {\n        return \"impossible\"\n    }\n    if ($mark -lt 0 -or $mark -gt 100) {\n        return \"always\"\n    }\n    if ($score -gt 90 -or $score -gt 80 -and $answer -gt 10) {\n        return \"pass\"\n    }\n    return \"fail\"\n}\n\nGet-Grade 50 1 60\n" },
        { "grade.rb", "def grade(mark, answer, score)\n  return \"impossible\" if mark >= 0 && mark <= 100\n  return \"always\" if mark < 0 || mark > 100\n  return \"pass\" if score > 90 || score > 80 && answer > 10\n  \"fail\"\nend\n\nputs grade(50, 1, 60)\n" },
        { "grade.rs", "fn grade(mark: i32, answer: i32, score: i32) -> &'static str {\n    if mark >= 0 && mark <= 100 {\n        return \"impossible\";\n    }\n    if mark < 0 || mark > 100 {\n        return \"always\";\n    }\n    if score > 90 || score > 80 && answer > 10 {\n        return \"pass\";\n    }\n    \"fail\"\n}\n\nfn main() {\n    println!(\"{}\", grade(50, 1, 60));\n}\n" },
        { "grade.ts", "function grade(mark: number, answer: number, score: number): string {\n  if (mark >= 0 && mark <= 100) {\n    return \"impossible\";\n  }\n  if (mark < 0 || mark > 100) {\n    return \"always\";\n  }\n  if (score > 90 || score > 80 && answer > 10) {\n    return \"pass\";\n  }\n  return \"fail\";\n}\n\nconsole.log(grade(50, 1, 60));\n" },
    };

    [Theory]
    [MemberData(nameof(Found))]
    public void ComparisonsThatDecideLessThanTheySeemToAreFound(string fileName, string code, string said)
    {
        Assert.Equal(said.Split('\n'), Scanned(fileName, code).Select(finding => $"{finding.Line}|{finding.PatternId}|{finding.Message}"));
    }

    [Theory]
    [MemberData(nameof(NearMisses))]
    public void ARangeItsOutsideAndAnAndTakenFirstAreLeftAlone(string fileName, string code)
    {
        Assert.Empty(Scanned(fileName, code));
    }
}
